8	// Correct 提交一次已确认回环校正。
9	//
10	// req.ID 必须非空；req.Anchor 必须准确命中一个已导入帧的时间（不能是
11	// 初始位姿，也不借用历史查询得到的最近一帧）；目标位姿数值必须有限、
12	// 目标方差必须非负。命中后，锚点帧采用提交的位姿；从锚点到提交时末帧
13	// 的轨迹整体平移并旋转（保持这些帧在校正前彼此的相对位置与朝向，时间
14	// 不变，朝向归一到既有范围）；锚点之后每帧的方差等于目标方差加上锚点
15	// 之后至该帧的原运动方差累计值。更早的位姿不变。
16	//
17	// 受影响帧中的路标观测随新位姿改变地图位置；更早观测的地图位置不变。
18	// 同一路标仍按全部已接受观测、依原时间与同帧输入次序做增量平均并遵守
19	// 合并距离限制；观测次数不变。若校正后出现路标冲突，整次校正拒绝并说
20	// 明冲突帧时间与路标。输入或校正结果含非有限数值同样拒绝。
21	//
22	// 同一标识以相同内容重复提交返回首次结果且不再修改数据；同一标识不同
23	// 内容明确拒绝。任何拒绝或保存失败都不改变轨迹、路标与既有校正记录。
24	// 旧文件缺少逐帧观测来源时，覆盖其历史范围的校正返回 RejectNoBasis。
25	func (m *Map) Correct(req Correction) (CorrectionRecord, error) {
26		m.mu.Lock()
27		defer m.mu.Unlock()
28		if m.closed {
29			return CorrectionRecord{}, ErrClosed
30		}
31		st := m.state
32	
33		// 已保存校正：相同内容直接返回首次记录；不同内容明确拒绝。
34		// 不做任何校验或状态变更，即使其后又提交过其他校正。
35		if hash, ok := st.corrIndex[req.ID]; ok {
36			if hash == canonicalCorrectionHash(req.Anchor, req.Target) {
37				return cloneRecord(st.correctionRecordByID(req.ID)), nil
38			}
39			return CorrectionRecord{}, &RejectError{Kind: RejectCorrectionMismatch, Landmark: req.ID, HasLandmark: true}
40		}
41	
42		if req.ID == "" {
43			return CorrectionRecord{}, &RejectError{Kind: RejectEmptyID}
44		}
45		tgt := req.Target
46		if !isFinite(tgt.X) || !isFinite(tgt.Y) || !isFinite(tgt.Heading) || !isFinite(tgt.Variance) {
47			return CorrectionRecord{}, &RejectError{Kind: RejectNonFinite, Time: req.Anchor, HasTime: true}
48		}
49		if tgt.Variance < 0 {
50			return CorrectionRecord{}, &RejectError{Kind: RejectNegativeVariance, Time: req.Anchor, HasTime: true}
51		}
52	
53		// 锚点必须准确命中已导入帧：trajectory[0] 是初始位姿，不能校正。
54		anchorIdx := -1
55		for j := 1; j < len(st.trajectory); j++ {
56			if st.trajectory[j].Time == req.Anchor {
57				anchorIdx = j
58				break
59			}
60		}
61		if anchorIdx < 0 {
62			return CorrectionRecord{}, &RejectError{Kind: RejectAnchorNotFound, Time: req.Anchor, HasTime: true}
63		}
64		end := len(st.trajectory) - 1
65	
66		// 受影响范围内每一帧都必须有逐帧依据（旧文件没有，不能靠推测校正）。
67		for k := anchorIdx - 1; k < len(st.sources); k++ {
68			if st.sources[k] == nil {
69				return CorrectionRecord{}, &RejectError{Kind: RejectNoBasis, Time: req.Anchor, HasTime: true}
70			}
71		}
72	
73		oldAnchor := st.trajectory[anchorIdx]
74		newHeading := normalizeAngle(tgt.Heading)
75		// 相对位姿整体旋转 δ；平移锚点到目标位置。
76		dHeading := normalizeAngle(newHeading - oldAnchor.Heading)
77		cosD, sinD := math.Cos(dHeading), math.Sin(dHeading)
78	
79		// ---- 在副本上推演新位姿，真实状态此时保持不变 ----
80		next := append([]Pose(nil), st.trajectory...)
81		accumVar := tgt.Variance
82		for j := anchorIdx; j <= end; j++ {
83			old := st.trajectory[j]
84			if j > anchorIdx {
85				accumVar += st.sources[j-1].moveVariance
86			}
87			dx := old.X - oldAnchor.X
88			dy := old.Y - oldAnchor.Y
89			np := Pose{
90				Time:     old.Time,
91				X:        tgt.X + cosD*dx - sinD*dy,
92				Y:        tgt.Y + sinD*dx + cosD*dy,
93				Heading:  normalizeAngle(old.Heading + dHeading),
94				Variance: accumVar,
95			}
96			if !isFinite(np.X) || !isFinite(np.Y) || !isFinite(np.Heading) || !isFinite(np.Variance) {
97				return CorrectionRecord{}, &RejectError{Kind: RejectNonFinite, Time: req.Anchor, HasTime: true}
98			}
99			next[j] = np
100		}
101	
102		// occKey 标识某一路标的某一次出现。回环校正跨越同一路标的多次出现
103		// 时，各次出现分别聚合、分别遵守合并距离限制。
104		type occKey struct {
105			id  string
106			num int
107		}
108	
109		// occAt 把时间 t 的一次观测归入当时的当前出现：各次出现的时间区间
110		// （首次观测时间 .. 失效时间）互不重叠。旧文件的第 1 次出现缺少逐帧
111		// 来源（hasFirstSeen 为假），覆盖最早的全部历史帧。
112		occAt := func(id string, t int64) int {
113			lm := st.landmarks[id]
114			for i, o := range lm.appearances {
115				if o.hasFirstSeen && o.firstSeenTime > t {
116					continue
117				}
118				if !o.active && o.invalidTime < t {
119					continue
120				}
121				return i + 1
122			}
123			return 0 // 不变量：已接受观测必然属于某次出现
124		}
125	
126		// 受影响的路标出现：在受影响帧中被观测到的全部（标识，出现编号）。
127		affected := make(map[occKey]struct{})
128		for j := anchorIdx; j <= end; j++ {
129			t := st.trajectory[j].Time
130			for _, ob := range st.sources[j-1].observations {
131				affected[occKey{id: ob.ID, num: occAt(ob.ID, t)}] = struct{}{}
132			}
133		}
134		affectedKeys := make([]occKey, 0, len(affected))
135		for k := range affected {
136			affectedKeys = append(affectedKeys, k)
137		}
138		sort.Slice(affectedKeys, func(i, j int) bool {
139			if affectedKeys[i].id != affectedKeys[j].id {
140				return affectedKeys[i].id < affectedKeys[j].id
141			}
142			return affectedKeys[i].num < affectedKeys[j].num
143		})
144	
145		// 逐“出现”运行聚合：旧文件第 1 次出现的既有观测作为固定“旧贡献”
146		// 起点（位置不随校正改变），其余观测按帧时间与同帧输入次序、以当前/
147		// 校正后位姿重放，完整复刻导入时的增量平均与合并距离判定。同一路标的
148		// 不同出现互不参与彼此的合并。
149		type agg struct {
150			count int
151			x, y  float64
152		}
153		aggs := make(map[occKey]*agg, len(affectedKeys))
154		for _, k := range affectedKeys {
155			occ := st.landmarks[k.id].appearances[k.num-1]
156			a := &agg{}
157			if occ.legacyCount > 0 {
158				a.count = occ.legacyCount
159				a.x = occ.legacyMX
160				a.y = occ.legacyMY
161			}
162			aggs[k] = a
163		}
164		for j := 1; j <= end; j++ {
165			src := st.sources[j-1]
166			if src == nil {
167				continue // 旧文件帧：观测已计入对应出现的 legacy 起点
168			}
169			pose := next[j]
170			t := st.trajectory[j].Time
171			for _, ob := range src.observations {
172				k := occKey{id: ob.ID, num: occAt(ob.ID, t)}
173				a, ok := aggs[k]
174				if !ok {
175					continue
176				}
177				mx, my := localToMap(pose.X, pose.Y, pose.Heading, ob.X, ob.Y)
178				if a.count > 0 && math.Hypot(mx-a.x, my-a.y) > st.config.MergeDistance {
179					return CorrectionRecord{}, &RejectError{
180						Kind:          RejectLandmarkConflict,
181						Time:          st.trajectory[j].Time,
182						HasTime:       true,
183						Landmark:      ob.ID,
184						HasLandmark:   true,
185						Occurrence:    k.num,
186						HasOccurrence: true,
187					}
188				}
189				a.x = mergeMean(a.x, mx, a.count)
190				a.y = mergeMean(a.y, my, a.count)
191				a.count++
192			}
193		}
194		for _, k := range affectedKeys {
195			a := aggs[k]
196			occ := st.landmarks[k.id].appearances[k.num-1]
197			if !isFinite(a.x) || !isFinite(a.y) {
198				return CorrectionRecord{}, &RejectError{Kind: RejectNonFinite, Time: req.Anchor, HasTime: true}
199			}
200			if a.count != occ.count {
201				// 内存不变量被破坏不可能由本包写出，按损坏处理而非半提交。
202				return CorrectionRecord{}, ErrCorrupt
203			}
204		}
205	
206		// ---- 组装校正前后快照（记录不可变） ----
207		rec := &CorrectionRecord{
208			ID:        req.ID,
209			Anchor:    req.Anchor,
210			Target:    tgt,
211			EndTime:   st.trajectory[end].Time,
212			Poses:     make([]PoseChange, 0, end-anchorIdx+1),
213			Landmarks: make([]LandmarkChange, 0, len(affectedKeys)),
214		}
215		for j := anchorIdx; j <= end; j++ {
216			rec.Poses = append(rec.Poses, PoseChange{Before: st.trajectory[j], After: next[j]})
217		}
218		for _, k := range affectedKeys {
219			occ := st.landmarks[k.id].appearances[k.num-1]
220			a := aggs[k]
221			rec.Landmarks = append(rec.Landmarks, LandmarkChange{
222				ID:         k.id,
223				Occurrence: k.num,
224				Before:     Landmark{ID: k.id, X: occ.x, Y: occ.y, Count: occ.count},
225				After:      Landmark{ID: k.id, X: a.x, Y: a.y, Count: a.count},
226			})
227		}
228	
229		// ---- 全部校验通过：暂存提交并落盘；落盘失败精确回滚 ----
230		oldTraj := append([]Pose(nil), st.trajectory...)
231		type occSnapshot struct {
232			key  occKey
233			occ  *occurrenceState
234			x, y float64
235		}
236		oldOcc := make([]occSnapshot, 0, len(affectedKeys))
237		for _, k := range affectedKeys {
238			occ := st.landmarks[k.id].appearances[k.num-1]
239			oldOcc = append(oldOcc, occSnapshot{key: k, occ: occ, x: occ.x, y: occ.y})
240		}
241		oldCorrLen := len(st.corrections)
242	
243		st.trajectory = next
244		for _, s := range oldOcc {
245			a := aggs[s.key]
246			s.occ.x, s.occ.y = a.x, a.y
247		}
248		st.corrections = append(st.corrections, rec)
249		st.corrIndex[req.ID] = canonicalCorrectionHash(req.Anchor, tgt)
250	
251		if err := m.saveReplace(); err != nil {
252			st.trajectory = oldTraj
253			for _, s := range oldOcc {
254				s.occ.x, s.occ.y = s.x, s.y
255			}
256			st.corrections = st.corrections[:oldCorrLen]
257			delete(st.corrIndex, req.ID)
258			return CorrectionRecord{}, err
259		}
260		return cloneRecord(rec), nil
261	}
262	
263	// Corrections 返回按提交次序排列的成功校正记录副本。记录一经生成永不
264	// 被后续校正改写；后续校正只是以当时最新状态为起点生成新记录。
265	func (m *Map) Corrections() ([]CorrectionRecord, error) {
266		m.mu.Lock()
267		defer m.mu.Unlock()
268		if m.closed {
269			return nil, ErrClosed
270		}
271		out := make([]CorrectionRecord, 0, len(m.state.corrections))
272		for _, rec := range m.state.corrections {
273			out = append(out, cloneRecord(rec))
274		}
275		return out, nil
276	}
277	
278	func (st *mapState) correctionRecordByID(id string) *CorrectionRecord {
279		for _, rec := range st.corrections {
280			if rec.ID == id {
281				return rec
282			}
283		}
284		return nil
285	}
286	
287	func cloneRecord(rec *CorrectionRecord) CorrectionRecord {
288		if rec == nil {
289			return CorrectionRecord{}
290		}
291		cp := *rec
292		cp.Poses = append([]PoseChange(nil), rec.Poses...)
293		cp.Landmarks = append([]LandmarkChange(nil), rec.Landmarks...)
294		return cp
295	}
